'use strict';
(() => {
const D=window.EPYLLION, gm=location.pathname.endsWith('/gm.html'), view=document.querySelector('#view');
const all=D.entries, byId=new Map(all.map(e=>[e.id,e]));
const categories={world:['龍域與龍族','DRAGONIA','從首都到荒野，認識這片由龍族建立的世界。','◎'],houses:['六大家族','THE GREAT HOUSES','傳統、歷史、家族義務，以及成年後的儀式。','⚑'],creation:['建立你的幼龍','CREATE A DRAKE','選擇扮演書、家族與美德，再與朋友組成龍群。','✎'],rules:['遊戲如何進行','PLAYING THE GAME','從故事出發，認識動作、擲骰與共同創作。','◇'],moves:['基本動作','BASIC MOVES','符合觸發條件時才使用動作；10+ 與 7–9 都算成功。','↗'],magic:['友誼與月之魔法','FRIENDSHIP & MAGIC','朋友給予力量，五輪月亮回應你們的呼喚。','☾'],shadow:['暗影與恢復','SHADOWS & DARKNESS','標記暗影後立即行動；朋友能帶你走出黑暗。','◐'],growth:['成長與聚會收尾','GROWING TOGETHER','從若鱗幼龍到上古巨龍，讓經歷成為力量。','♧'],playbooks:['選擇你的扮演書','THE PLAYBOOKS','每種幼龍都有值得珍惜的天賦，也有需要朋友的時刻。','♧'],gm:['龍主的目標與原則','THE DRAGONMASTER','讓龍域充滿龍族特質，讓選擇有意義，用玩的去發現。','♜'],'gm-moves':['龍主動作','DRAGONMASTER MOVES','以荒野、文化與黑暗回應龍群的選擇。','↗'],'first-session':['第一次冒險','THE FIRST SESSION','共同畫出龍域，在第一場遊戲中找到冒險。','✎'],hazards:['危害與自訂動作','HAZARDS & CUSTOM MOVES','記錄尚未解決的問題，讓月相推動故事。','◔'],examples:['原書遊玩範例','EXAMPLES OF PLAY','跟著原書的龍群，觀察對話如何觸發動作。','☷'],expansion:['龍族百科','ENCYCLOPEDIA DRACONICA','十七篇傳說與故事，延伸龍域的歷史、奇觀與冒險。','✦'],'expansion-playbooks':['四種擴充扮演書','MORE DRAKES','元素使、使節、孤龍與反叛者。','♧']};
const gmCats=new Set(['gm','gm-moves','first-session','hazards','examples']);
const cross=e=>gmCats.has(e.category)||(gm&&e.category.startsWith('expansion'))?'gm.html?v=epyllion-10':'index.html?v=epyllion-10';
const entryUrl=e=>`${cross(e)}#entry/${encodeURIComponent(e.id)}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=gm?'epyllion-gm-favorites-v1':'epyllion-player-favorites-v1';let favorites;
try{favorites=new Set(JSON.parse(localStorage.getItem(key)||'[]').filter(x=>byId.has(x)))}catch{favorites=new Set()}
let filter={q:'',book:'',role:''}, active='home', currentEntries=[], expanded=false;
const textOf=e=>[e.title,e.en,e.stat,e.note,...(e.paragraphs||[]),...(e.bullets||[]),e.source.book].join(' ');
const normalize=s=>String(s).normalize('NFKC').toLowerCase().replace(/[\s+＋−–—-]/g,'');
const searchIndex=new Map(all.map(e=>[e.id,normalize(textOf(e))]));
function selected(){return all.filter(e=>gm?gmCats.has(e.category)||e.category.startsWith('expansion'):!gmCats.has(e.category))}
function categoryName(c){return categories[c]?.[0]||(c==='playbook-moves'?'扮演書專屬動作':c)}
function nav(){let groups=gm?[['home','⌂','龍主工作台'],['gm','♜','目標與原則'],['gm-moves','↗','龍主動作'],['first-session','✎','第一次冒險'],['hazards','◔','危害與自訂動作'],['examples','☷','遊玩範例'],['expansion','✦','龍族百科'],['expansion-playbooks','♧','擴充扮演書']]:[['home','⌂','查閱首頁'],['world','◎','龍域與龍族'],['houses','⚑','六大家族'],['creation','✎','建立你的幼龍'],['playbooks','♧','全部扮演書'],['rules','◇','遊戲如何進行'],['moves','↗','基本動作'],['magic','☾','友誼與魔法'],['shadow','◐','暗影與恢復'],['growth','♧','成長與聚會收尾']];
document.querySelector('#navigation').innerHTML=`<p class="nav-label">${gm?'龍主的桌邊手冊':'龍群的隨身手冊'}</p>`+groups.map(([id,icon,title])=>`<a class="nav-link ${active===id?'active':''}" href="#${id}" ${active===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${title}</a>`).join('')+`<div class="nav-split"></div>`+(!gm?`<a class="nav-link ${active==='expansion'?'active':''}" href="#expansion"><span class="nav-icon">✦</span>龍族百科</a><a class="nav-link ${active==='expansion-playbooks'?'active':''}" href="#expansion-playbooks"><span class="nav-icon">♧</span>擴充扮演書</a>`:'')+`<a class="nav-link ${active==='favorites'?'active':''}" href="#favorites"><span class="nav-icon">☆</span>我的收藏 <small>${favorites.size}</small></a><a class="nav-link ${active==='glossary'?'active':''}" href="#glossary"><span class="nav-icon">≡</span>中英用詞</a><a class="nav-link ${active==='downloads'?'active':''}" href="#downloads"><span class="nav-icon">↓</span>閱讀與下載</a><a class="nav-link" href="${gm?'index.html?v=epyllion-10':'gm.html?v=epyllion-10'}#home"><span class="nav-icon">${gm?'☾':'♜'}</span>${gm?'回到玩家手冊':'前往龍主工作台'} ↗</a>`;}
function head(title,en,desc=''){return `<div class="page-head"><span class="eyebrow">${esc(en)}</span><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>`}
const quick=(id,n,title,desc)=>`<a class="quick-card" href="#${id}"><span class="index">${n}</span><h3>${title}</h3><p>${desc}</p><span class="arrow">↗</span></a>`;
function home(){if(gm){view.innerHTML=head('讓龍群的選擇有意義。','THE DRAGONMASTER’S FIELD GUIDE','你不必預寫所有答案。描繪充滿奇蹟的龍域，提出問題，跟隨龍群的選擇，發現故事。')+`<img class="entry-image" src="assets/standing_up_to_darkness.webp" alt="幼龍們挺身面對黑暗，Jason Poole 原繪"><div class="workflow"><a href="#first-session"><b>01 · 開始之前</b><h3>一起創造龍域</h3><p>安全工具、角色介紹與地圖，從玩家的答案開始。</p></a><a href="#gm"><b>02 · 冒險之中</b><h3>記住你的原則</h3><p>成為角色的粉絲，賦予每隻龍名字與渴望。</p></a><a href="#gm-moves"><b>03 · 回應選擇</b><h3>讓世界行動</h3><p>荒野、文化、黑暗的軟動作與硬動作。</p></a><a href="#hazards"><b>04 · 聚會之間</b><h3>推進尚存危害</h3><p>家人、友誼、傳統與自然，月相逐步接近滿月。</p></a></div><div class="section-heading"><h2>桌邊常用</h2><span>依原書章節查閱</span></div><div class="quick-grid">${quick('gm-moves','01','龍主動作','讓每一次回應都根植於故事。')}${quick('examples','02','遊玩範例','原書對話、選擇與動作示範。')}${quick('expansion','03','龍族百科','將龍域的傳說加入你的遊戲。')}</div><div class="callout">玩家與龍主入口是閱讀分區，不是存取權限控制。收藏分別保存在目前瀏覽器。</div>`;return;}
view.innerHTML=`<section class="hero"><div><span class="eyebrow">A LITTLE EPIC · A WORLD OF DRAGONS</span><h1>小小的翅膀，<br>不凡的史詩。</h1><p>在五輪月亮照耀的大地，<br>你們是一群年輕的龍。<br>以友誼抵禦黑暗，寫下屬於龍群的故事。</p><div class="hero-actions"><a class="button primary" href="#creation">開始你的冒險 <span>→</span></a><a class="button" href="#moves">查閱基本動作 <span>↗</span></a></div></div><img class="hero-art" src="assets/group.webp" alt="六隻神態各異的幼龍組成龍群，Jason Poole 原繪"><p class="hero-caption">Epyllion 原書插畫 · Jason Poole</p></section><div class="section-heading"><h2>帶著手冊，展翼出發。</h2><span>THE CLUTCH’S COMPANION</span></div><div class="quick-grid">${quick('moves','01','故事正在發生','觸發條件、擲骰與結果，桌邊快速查閱。')}${quick('playbooks','02','你是哪一種龍？','核心六種、擴充四種；完整選項與動作一次閱讀。')}${quick('magic','03','朋友就是力量','友誼寶石、五輪月亮與自由的魔法。')}</div><div class="dice-bar"><strong>2d6 ＋ 修正</strong><div class="dice-result"><b>10+</b>完全成功</div><div class="dice-result"><b>7–9</b>成功，附帶代價</div><div class="dice-result"><b>6−</b>故事轉折，獲得經驗</div></div><div class="reading-grid"><div><span class="eyebrow">WELCOME TO DRAGONIA</span><h2 style="margin:10px 0 15px">這一次，龍就是你。</h2><p>《龍族史詩》是一款關於友誼、魔法與成長的桌上角色扮演遊戲。在龍主與玩家的對話中，你們探索龍域的古老傳統，協助需要幫助的龍，並共同對抗悄然滋長的黑暗。</p><p style="margin-top:12px">先描述角色的行動，再讓動作與骰子帶領故事。用玩的去發現。</p><a href="#entry/introduction" class="button" style="margin-top:19px">認識 Epyllion ↗</a></div><div><div class="section-heading" style="margin-top:0"><h3>循著月光閱讀</h3></div><div class="mini-list"><a href="#world"><small>CH. 01</small>龍域、歷史與六大家族 <span>↗</span></a><a href="#creation"><small>CH. 02</small>建立幼龍，組成龍群 <span>↗</span></a><a href="#growth"><small>CH. 03</small>從每一場冒險成長 <span>↗</span></a><a href="gm.html?v=epyllion-10#home"><small>FOR THE DM</small>打開龍主工作台 <span>↗</span></a></div></div></div><p class="coverage">${D.stats.total} 個翻譯條目 · 核心規則與龍族百科 · <a href="#about">查看收錄範圍與校訂</a></p>`;}
function body(e){return (e.image?`<img class="entry-image" src="${esc(e.image)}" alt="${esc(e.title)}原書插畫">`:'')+(e.paragraphs||[]).map(p=>`<p>${esc(p)}</p>`).join('')+((e.bullets||[]).length?`<ul>${e.bullets.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:'')+(e.note?`<div class="entry-note">${esc(e.note)}</div>`:'');}
function card(e,single=false){
 const p=e.paragraphs||[],brief=p[0]||'',rest={...e,paragraphs:p.slice(1)};
 const detail=p.length>1||(e.bullets||[]).length||e.note||e.image;
 const content=single?body(e):`<p>${esc(brief)}</p>${detail?`<details ${expanded?'open':''}><summary>閱讀完整內容與說明</summary><div>${body(rest)}</div></details>`:''}`;
 return `<article class="entry ${single?'entry-single':''}" id="${esc(e.id)}"><div class="entry-top"><div class="entry-title">${e.stat?`<span class="tag">擲＋${esc(e.stat)}</span>`:''}<h2>${single?esc(e.title):`<a href="${entryUrl(e)}">${esc(e.title)}</a>`}</h2><span class="en">${esc(e.en)}</span></div><button class="pin" data-action="pin" data-id="${esc(e.id)}" aria-label="${favorites.has(e.id)?'取消收藏':'收藏'} ${esc(e.title)}" aria-pressed="${favorites.has(e.id)}">${favorites.has(e.id)?'★':'☆'}</button></div><div class="entry-body">${content}</div><div class="entry-meta"><a target="_blank" rel="noopener" href="${sourceUrl(e)}">${esc(e.source.book)} · ${esc(e.source.pages)} 頁 ↗</a><button class="text-btn" data-action="copy" data-id="${esc(e.id)}">複製連結</button><span class="kind">${esc(e.kind)}</span></div></article>`;
}
function sourceUrl(e){const source=D.sources[e.source.file];if(!source)return '#about';const primary=e.source_ref?.pdf_ranges?.[0]?.start;const n=String(e.source.pages).match(/\d+/);const fallback=(n?Number(n[0]):1)+(/^PDF\s/i.test(e.source.pages)?0:(source.offset||0));return `${source.path}#page=${primary||fallback}`;}
function tools(entries){const books=[...new Set(entries.map(e=>e.source.book))];const roles=[...new Set(entries.map(e=>e.role).filter(Boolean))];return `<div class="tools"><input id="filter-q" aria-label="篩選本頁條目" type="search" placeholder="在本頁查找名稱、效果或關鍵字…" value="${esc(filter.q)}"><select id="filter-book" aria-label="篩選來源"><option value="">全部來源</option>${books.map(b=>`<option ${b===filter.book?'selected':''}>${esc(b)}</option>`).join('')}</select>${roles.length?`<select id="filter-role" aria-label="篩選扮演書"><option value="">全部扮演書</option>${roles.map(r=>`<option value="${esc(r)}" ${r===filter.role?'selected':''}>${esc(D.roles[r]?.title||r)}</option>`).join('')}</select>`:''}<button class="focus-toggle" data-action="expand">${expanded?'收合說明':'展開說明'}</button><button class="focus-toggle" data-action="focus">專注閱讀</button></div><div class="count-line"><span id="count"></span><span>☆ 收藏 · 點擊標題單獨閱讀</span></div><div id="entries"></div>`;}
function updateList(){const q=normalize(filter.q);const entries=currentEntries.filter(e=>(!q||searchIndex.get(e.id).includes(q))&&(!filter.book||e.source.book===filter.book)&&(!filter.role||e.role===filter.role));document.querySelector('#count').textContent=`顯示 ${entries.length} / ${currentEntries.length} 個條目`;document.querySelector('#entries').innerHTML=entries.map(e=>card(e)).join('')||'<div class="empty">沒有符合的條目。試試其他關鍵字或清除篩選。</div>';}
function listing(cat){if(cat==='playbooks'||cat==='expansion-playbooks'){playbookIndex(cat==='expansion-playbooks');return;}const config=categories[cat]||['我的收藏','YOUR BOOKMARKS','收藏保存在目前瀏覽器，方便遊戲時隨手查閱。'];currentEntries=cat==='favorites'?selected().filter(e=>favorites.has(e.id)):all.filter(e=>e.category===cat||(cat==='playbooks'&&e.category==='playbook-moves')||(cat==='moves'&&['moon-magic','shadow-magic'].includes(e.id)));let extra='';if(cat==='playbooks'){const roles=all.filter(e=>e.category==='playbooks'&&e.role);extra=`<div class="role-grid">${roles.map(e=>`<a class="role-card" href="${entryUrl(e)}">${e.image?`<img src="${esc(e.image)}" alt="${esc(e.title)}">`:''}<small>${esc(e.en)}</small><h3>${esc(e.title)}</h3><p>${esc((e.paragraphs?.[0]||'').slice(0,65))}…</p></a>`).join('')}</div>`;}if(cat==='creation')extra=creationSteps();view.innerHTML=head(config[0],config[1],config[2])+extra+tools(currentEntries);updateList();}
function creationSteps(){return `<div class="steps">${[['挑選一種扮演書','每種扮演書提供一種獨特的幼龍。核心六種，擴充另有四種。','playbooks'],['決定名字、外觀與顏色','每列外觀選一項；挑選容易區別的友誼寶石顏色。','playbooks'],['家族、義務與屬性','選家族及對應義務，再將一項起始屬性加一。','houses'],['選美德與動作','保留特色動作，再選一項起始額外動作。美德是你欣賞朋友的特質。','playbooks'],['介紹彼此，建立關係','填入夥伴名字、說明過往經歷，照指示交換寶石。','playbooks'],['共同畫出龍域','回答龍主的問題，在地圖加入家園、地標與尚未解開的謎團。','world']].map(([t,p,r])=>`<section class="step"><h3>${t}</h3><p>${p}</p><a href="#${r}">查閱相關內容 ↗</a></section>`).join('')}</div><div class="section-heading"><h2>創角規則詳讀</h2><span>依原書順序</span></div>`;}
function single(id){const book=D.playbooks.find(b=>b.entry_id===id||b.sections.some(s=>s.entry_id===id));if(book){fullPlaybook(book,id);return;}const e=byId.get(id);if(!e){view.innerHTML=head('找不到這個條目','ENTRY NOT FOUND')+'<p><a href="#home">回到首頁</a>，或使用搜尋尋找相關規則。</p>';return;}active=e.category==='playbook-moves'?'playbooks':e.category;const siblings=all.filter(x=>x.category===e.category),i=siblings.indexOf(e);view.innerHTML=`<div class="breadcrumbs"><a href="#home">${gm?'龍主工作台':'玩家手冊'}</a> ／ <a href="#${active}">${esc(categoryName(active))}</a></div>`+card(e,true)+`<div class="entry-nav">${i>0?`<a href="${entryUrl(siblings[i-1])}">← ${esc(siblings[i-1].title)}</a>`:'<span></span>'}${i<siblings.length-1?`<a href="${entryUrl(siblings[i+1])}">${esc(siblings[i+1].title)} →</a>`:''}</div><button data-action="focus" class="focus-toggle">切換專注閱讀</button> <button data-action="print" class="focus-toggle">列印本條目</button>`;if(e.role){const moves=all.filter(x=>x.role===e.role&&x.id!==id);if(moves.length)view.innerHTML+=`<div class="section-heading"><h2>同一扮演書</h2></div><div class="mini-list">${moves.map(x=>`<a href="${entryUrl(x)}">${esc(x.title)} <span>↗</span></a>`).join('')}</div>`;}}

function pdfAsset(s){return s.path+(["zh-playbooks","zh-ed-playbooks"].includes(s.id)?"?v=20261024-r2":"");}
function blockText(r){return byId.get(r.entry_id)[r.field][r.index];}
function readingText(text){return esc(text).replace(/([①②③])/g,'<br>$1').replace(/；/g,'；<wbr>');}
function playbookIndex(expansionOnly=false){
 active=expansionOnly?'expansion-playbooks':'playbooks';const books=D.playbooks.filter(b=>!expansionOnly||b.edition==='expansion');
 view.innerHTML=head(expansionOnly?'四種擴充扮演書':'十種龍，十條冒險之路。','THE COMPLETE PLAYBOOKS','選一隻龍，直接閱讀創角選項、全部五個專屬動作、進階、成長與暗影化身。')+
 `<div class="book-index-tools"><label>尋找扮演書<input id="book-filter" type="search" placeholder="名稱、動作或關鍵字…"></label><a class="button" href="${pdfAsset(D.sources['zh-playbooks'])}">核心中文角色卡 ↓</a><a class="button" href="${pdfAsset(D.sources['zh-ed-playbooks'])}">擴充中文角色卡 ↓</a>${expansionOnly?'<a href="#playbooks">查看全部十種 ↗</a>':''}</div><div id="book-index">`+
 ['core','expansion'].map(edition=>{const list=books.filter(b=>b.edition===edition);return list.length?`<section class="book-edition"><div class="section-heading"><h2>${edition==='core'?'核心扮演書':'擴充扮演書'}</h2><span>${list.length} 種 · 每種五個專屬動作</span></div><div class="role-grid">${list.map(b=>`<a class="role-card complete-role" data-book="${b.id}" href="${entryUrl(byId.get(b.entry_id))}">${b.image?`<img src="${esc(b.image)}" alt="">`:`<div class="role-symbol" aria-hidden="true">${{elementalist:'◇',envoy:'◎',orphan:'☾',rebel:'✦'}[b.id]}</div>`}<small>${esc(b.en)}</small><h3>${esc(b.title)}</h3><p>${esc(byId.get(b.entry_id).paragraphs[0])}</p><span class="role-read">打開完整扮演書 →</span></a>`).join('')}</div></section>`:''}).join('')+`<p id="book-empty" class="empty" hidden>沒有符合的扮演書。試試其他名稱或動作。</p></div>`;
 if(expansionOnly){view.innerHTML+=`<div class="section-heading"><h2>擴充扮演書的使用建議</h2></div>${card(byId.get('ed-playbooks-intro'),true)}`;}
}
function filterBooks(query){const q=normalize(query);document.querySelectorAll('[data-book]').forEach(el=>{const b=D.playbooks.find(x=>x.id===el.dataset.book);const text=b.sections.flatMap(s=>s.blocks.map(blockText)).join(' ')+b.title+b.en;el.hidden=!!q&&!normalize(text).includes(q);});document.querySelectorAll('.book-edition').forEach(el=>el.hidden=![...el.querySelectorAll('[data-book]')].some(x=>!x.hidden));document.querySelector('#book-empty').hidden=!!document.querySelector('[data-book]:not([hidden])');}
function fullPlaybook(b,target){
 active=b.edition==='core'?'playbooks':'expansion-playbooks';const e=byId.get(b.entry_id),source=D.sources[b.pdf_id];
 const anchor=s=>`${b.id}-${s.id}`;
 view.innerHTML=`<div class="breadcrumbs"><a href="#playbooks">全部扮演書</a> ／ ${b.edition==='core'?'核心':'擴充'} ／ ${esc(b.title)}</div><article class="playbook-full"><header class="book-hero">${b.image?`<img src="${esc(b.image)}" alt="${esc(b.title)}原書插畫">`:''}<div><span class="eyebrow">${esc(b.en)}</span><h1>${esc(b.title)}</h1><p>${esc(e.paragraphs[0])}</p><div class="book-actions"><button data-action="pin" data-id="${e.id}" aria-label="${favorites.has(e.id)?'取消收藏':'收藏'} ${esc(b.title)}" aria-pressed="${favorites.has(e.id)}">${favorites.has(e.id)?'★':'☆'}</button><a class="button" href="${pdfAsset(source)}#page=${b.pdf_page}" target="_blank" rel="noopener">中文角色卡 PDF ↗</a><button data-action="print">列印扮演書</button></div></div></header><nav class="book-toc" aria-label="本扮演書段落">${[['creation','屬性與家族'],['appearance','設定選項'],['fellowship','夥伴關係'],['starting','全部動作'],['growth','成長'],['shadows','暗影與恢復']].map(([id,title])=>`<button data-action="book-jump" data-target="${b.id}-${id}">${title}</button>`).join('')}</nav><div class="book-content">`+
 b.sections.filter(s=>s.id!=='identity').sort((a,c)=>{const order=s=>s.id==='growth'?90:s.id==='shadows'?100:b.sections.indexOf(s);return order(a)-order(c);}).map(section=>`<section class="book-section ${section.move?'book-move':''} ${section.signature?'signature-move':''}" id="${anchor(section)}">${section.signature?'<span class="tag">特色動作 · 起始取得</span>':section.move?'<span class="tag">其他動作 · 起始再選一個</span>':''}<h2>${esc(section.title)}</h2>${section.en?`<span class="en">${esc(section.en)}</span>`:''}<div class="book-blocks">${section.blocks.map(r=>`<${r.field==='bullets'?'div':'p'} class="${r.field==='bullets'?'book-option':''}" data-content="${r.entry_id}:${r.field}:${r.index}">${readingText(blockText(r))}</${r.field==='bullets'?'div':'p'}>`).join('')}</div></section>`).join('')+
 `</div><div class="entry-meta"><a href="${sourceUrl(e)}" target="_blank" rel="noopener">${esc(e.source.book)} · ${esc(e.source.pages)} 頁 ↗</a><button class="text-btn" data-action="copy" data-id="${e.id}">複製扮演書連結</button><span>完整創角選項與五個專屬動作</span></div></article><div class="book-switcher"><h2>其他扮演書</h2>${D.playbooks.filter(x=>x.id!==b.id).map(x=>`<a class="button" href="${entryUrl(byId.get(x.entry_id))}">${esc(x.title)}</a>`).join('')}</div>`;
 if(target!==b.entry_id){const section=b.sections.find(s=>s.entry_id===target);if(section)requestAnimationFrame(()=>document.getElementById(anchor(section))?.scrollIntoView());}
}

function downloads(){view.innerHTML=head('閱讀與下載','AT YOUR TABLE','中文核心與擴充角色卡依同一份網站校訂資料產生，每種扮演書兩頁，可直接下載列印。基本動作表仍保留既有版本；原文資料供對照查閱。')+`<div class="download-grid">${Object.values(D.sources).map(s=>`<section class="download-card"><span class="eyebrow">${s.language==='zh'?'TRADITIONAL CHINESE':'SOURCE MATERIAL'}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><a class="button" target="_blank" rel="noopener" href="${pdfAsset(s)}">開啟 PDF ↗</a> <a class="button" download href="${pdfAsset(s)}">下載 ↓</a></section>`).join('')}</div><div class="section-heading"><h2>一起繪製龍域</h2><span>點擊地圖放大</span></div><button data-action="map" style="padding:0;border:0;width:100%"><img class="map-image" src="assets/epyllionmap2.webp" alt="尚待龍群共同填入地標的龍域空白地圖"></button><p class="coverage">地圖來源：Epyllion EPUB 原圖 · 製圖 Stentor Danielson。</p>`;}
function glossary(){view.innerHTML=head('中英用詞','WORDS OF DRAGONIA','以既有中文資料的譯名為基礎，保留英文名稱供搜尋與對照。')+`<div class="table-wrap"><table><thead><tr><th>中文</th><th>English</th><th>查閱</th></tr></thead><tbody>${D.glossary.map(([zh,en,id])=>`<tr><td>${esc(zh)}</td><td>${esc(en)}</td><td>${id&&byId.has(id)?`<a href="${entryUrl(byId.get(id))}">閱讀 ↗</a>`:'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function qualityPanel(){if(!D.quality)return '';return `<div class="section-heading"><h2>翻譯品質記錄</h2></div><div class="callout"><p>已收錄 ${D.stats.total} 條。結構、來源檔及發布一致性另行檢查；${D.quality.source_checked||0} 條完成原文逐段初校，${D.quality.reviewed} 條完成獨立語義複核，${D.quality.pending} 條仍待複核。</p><p>頁碼範圍與條目數不能證明每個原文段落都已完整翻譯。既有內容不追認為通過正式語義審核。<a href="translation-quality.json" target="_blank" rel="noopener">查看檢查結果 ↗</a> · <a href="https://github.com/Eagle0425/epyllion-zh-tw-reference/blob/main/translation/PROOFREADING.md" target="_blank" rel="noopener">初校修正與原文疑義 ↗</a></p></div>`;}
function about(){view.innerHTML=head('讓每段譯文都有來處','SOURCES & EDITORIAL NOTES','本網站依工作區提供的核心規則、獨立扮演書、動作表及《龍族百科》整理。英文標題保留供查找，正文以繁體中文閱讀。')+`<div class="callout"><p>非官方翻譯與參考整理。Epyllion 遊戲文字及商標權利屬 Magpie Games 與各原作者；原書插畫 Jason Poole，製圖 Stentor Danielson。本網站未將原作文字與圖片宣告為開源授權。</p></div><h2>收錄範圍</h2><p class="coverage">目前 ${D.stats.total} 個條目、${D.stats.chars.toLocaleString()} 個中文字元。收錄核心規則各章、動作與範例、六種核心扮演書，以及《龍族百科》十七篇文章、特殊動作與四種擴充扮演書。所有條目標示來源與頁碼；正文以原書段落翻譯整理，重複的角色卡通用規則整合查閱。</p><div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>區域</th><th>條目數</th></tr></thead><tbody>${Object.entries(D.stats.categories).map(([c,n])=>`<tr><td>${esc(categoryName(c))}</td><td>${n}</td></tr>`).join('')}</tbody></table></div><div class="section-heading"><h2>網站校訂</h2></div><div class="entry-body"><p>「研讀他龍」依核心第 62 頁及英文動作表，修正為 10+ 問兩題、7–9 問一題。原中文 PDF 的兩個數值相反。</p><p>經驗值依核心第 72 頁：擲出失手（6−）或動作明確指示時獲得，不是每次擲骰皆有。協助或妨礙使用來自該夥伴的寶石，上限＋3；月之魔法的返還數量不套用此上限。</p><p>成年牙龍的額外動作可來自另一種扮演書；勇者的家族義務、先知美德及動作細節以英文獨立角色表核對。中文核心與擴充角色卡已依網站資料重製；基本動作表仍保留原始版本。</p><p>頁碼未寫 PDF 時，指書內印刷頁碼；來源連結直接定位對應 PDF 頁面。網站插畫擷取自使用者提供的 EPUB 原圖，僅轉換格式。</p></div><div class="section-heading"><h2>閱讀方式與隱私</h2></div><div class="entry-body"><p>網站參考 <a href="https://github.com/Eagle0425/root-rpg-player-reference" target="_blank" rel="noopener">Root RPG 玩家參考網站 ↗</a>的分區、搜尋、收藏與永久連結方式；Epyllion 的版面與資料另行建立。所有檔案採相對路徑，也可部署至 GitHub Pages 子目錄。</p><p>收藏僅存於瀏覽器 localStorage；玩家與龍主分開儲存。不需帳號即可使用網頁功能，沒有分析追蹤。網站使用工作區提供、隨站託管的 Jason 手寫字體，依標題、區塊、小標與內文分工。網站的託管存取權限由發布服務管理。可用瀏覽器列印功能列印條目。</p></div>`+qualityPanel();}
function render(){filter={q:'',book:'',role:''};document.body.classList.remove('menu-open');let h;try{h=decodeURIComponent(location.hash.slice(1)||'home')}catch{h='home'}active=h.startsWith('entry/')?'':h;if(h.startsWith('entry/'))single(h.slice(6));else if(h==='home')home();else if(h==='downloads')downloads();else if(h==='glossary')glossary();else if(h==='about')about();else if(categories[h]||h==='favorites')listing(h);else{view.innerHTML=head('找不到這一頁','PAGE NOT FOUND')+'<a href="#home">回到首頁</a>';}nav();document.title=`${h==='home'?(gm?'龍主工作台':'繁體中文手冊'):(view.querySelector('h1,h2')?.textContent||'手冊')}｜龍族史詩 Epyllion`;window.scrollTo({top:0,behavior:'instant'});}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2300);}
function results(){const q=normalize(document.querySelector('#search-input').value),target=document.querySelector('#search-results');if(!q){target.innerHTML='<p class="search-tips">輸入關鍵字，搜尋目前手冊全部條目與內文。</p>';return;}const found=selected().filter(e=>searchIndex.get(e.id).includes(q)).sort((a,b)=>Number(normalize(b.title+b.en).includes(q))-Number(normalize(a.title+a.en).includes(q)));target.innerHTML=`<p class="search-tips">找到 ${found.length} 個條目${found.length>60?'，顯示前 60 筆':''}</p>`+found.slice(0,60).map(e=>{const s=textOf(e),pos=normalize(s).indexOf(q);const exact=s.toLowerCase().indexOf(document.querySelector('#search-input').value.toLowerCase());const start=Math.max(0,exact-35);return `<a class="result" href="${entryUrl(e)}"><small>${esc(categoryName(e.category))} · ${esc(e.source.pages)} 頁</small><strong>${esc(e.title)}</strong><p>${start?'…':''}${esc(s.slice(start,start+140))}…</p></a>`;}).join('');}
document.addEventListener('click',async ev=>{if(ev.target.closest('.skip')){ev.preventDefault();document.querySelector('#main').focus();document.querySelector('#main').scrollIntoView();return;}const a=ev.target.closest('[data-action]');if(!a){if(ev.target.closest('#search-results a'))document.querySelector('#search-dialog').close();if(ev.target.closest('#navigation a'))document.body.classList.remove('menu-open');return;}const act=a.dataset.action,id=a.dataset.id;if(act==='menu'){document.body.classList.toggle('menu-open');document.querySelectorAll('[data-action="menu"]').forEach(b=>b.setAttribute('aria-expanded',String(document.body.classList.contains('menu-open'))));}if(act==='search'){document.querySelector('#search-dialog').showModal();document.querySelector('#search-input').focus();results();}if(act==='close-search')document.querySelector('#search-dialog').close();if(act==='close-art')document.querySelector('#art-dialog').close();if(act==='pin'){if(favorites.has(id))favorites.delete(id);else favorites.add(id);try{localStorage.setItem(key,JSON.stringify([...favorites]))}catch{toast('瀏覽器無法保存收藏；目前頁面仍可使用。')}a.textContent=favorites.has(id)?'★':'☆';a.setAttribute('aria-pressed',favorites.has(id));a.setAttribute('aria-label',`${favorites.has(id)?'取消收藏':'收藏'} ${byId.get(id).title}`);nav();if(active==='favorites')updateFavorites();else toast(favorites.has(id)?'已加入收藏':'已取消收藏');}if(act==='copy'){const e=byId.get(id),url=new URL(entryUrl(e),location.href).href;try{await navigator.clipboard.writeText(url);toast('已複製條目連結')}catch{toast('無法自動複製，請開啟條目並複製網址。')}}if(act==='expand'){expanded=!expanded;a.textContent=expanded?'收合說明':'展開說明';document.querySelectorAll('#entries details').forEach(x=>x.open=expanded);}if(act==='focus'){document.body.classList.toggle('focus-mode');a.textContent=document.body.classList.contains('focus-mode')?'退出專注閱讀':'專注閱讀';}if(act==='book-jump')document.getElementById(a.dataset.target)?.scrollIntoView({behavior:'smooth'});if(act==='print')window.print();if(act==='map'){document.querySelector('#art-image').src='assets/epyllionmap2.webp';document.querySelector('#art-image').alt='龍域空白地圖';document.querySelector('#art-caption').textContent='Epyllion 原書地圖 · Stentor Danielson';document.querySelector('#art-dialog').showModal();}});
function updateFavorites(){currentEntries=selected().filter(e=>favorites.has(e.id));updateList();}
document.addEventListener('input',e=>{if(e.target.id==='book-filter')filterBooks(e.target.value);if(e.target.id==='filter-q'){filter.q=e.target.value;updateList()}if(e.target.id==='search-input')results()});document.addEventListener('change',e=>{if(e.target.id==='filter-book'){filter.book=e.target.value;updateList()}if(e.target.id==='filter-role'){filter.role=e.target.value;updateList()}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/input|textarea|select/i.test(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();document.querySelector('[data-action="search"]').click()}if(e.key==='Escape')document.body.classList.remove('menu-open')});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));window.addEventListener('hashchange',render);render();
})();
